import hashlib
import hmac
import os
import struct
import time
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
import secrets

# Configuration
SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
SESSION_DURATION = 3600  # 1 hour
MAX_SESSIONS = 1000

class SessionStore:
    def __init__(self):
        self._sessions = {}
        self._lock_counter = 0

    def create_session(self, user_id, role='user'):
        session_id = secrets.token_hex(16)
        now = int(time.time())
        session_data = {
            'user_id': user_id,
            'role': role,
            'created_at': now,
            'expires_at': now + SESSION_DURATION
        }
        self._sessions[session_id] = session_data
        return session_id, self._sign_session(session_id, session_data)

    def _sign_session(self, session_id, data):
        # Pack session into binary token
        # Format: session_id(32) + user_id(4) + role_flag(1) + created_at(4) + expires_at(4) + hmac(32)
        user_id_bytes = struct.pack('>I', data['user_id'])
        role_flag = b'\x01' if data['role'] == 'admin' else b'\x00'
        created_bytes = struct.pack('>I', data['created_at'])
        expires_bytes = struct.pack('>I', data['expires_at'])

        payload = session_id.encode() + user_id_bytes + role_flag + created_bytes + expires_bytes
        tag = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        return (payload + tag).hex()

    def validate_token(self, token_hex):
        try:
            token = bytes.fromhex(token_hex)
        except (ValueError, TypeError):
            return None

        if len(token) != 77:  # 32 + 4 + 1 + 4 + 4 + 32
            return None

        payload = token[:45]
        received_tag = token[45:]

        expected_tag = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        if not hmac.compare_digest(received_tag, expected_tag):
            return None

        # Parse validated payload
        session_id = payload[:32].decode()
        user_id = struct.unpack('>I', payload[32:36])[0]
        role_flag = payload[36]
        created_at = struct.unpack('>I', payload[37:41])[0]
        expires_at = struct.unpack('>I', payload[41:45])[0]

        # Check expiration
        if not self._check_expiry(created_at, expires_at):
            return None

        return {
            'session_id': session_id,
            'user_id': user_id,
            'role': 'admin' if role_flag == 1 else 'user',
            'created_at': created_at,
            'expires_at': expires_at
        }

    def _check_expiry(self, created_at, expires_at):
        """Validate session has not expired.

        Uses signed 32-bit arithmetic to handle clock skew gracefully.
        Returns True if session is still valid.
        """
        now = int(time.time())
        # Convert to signed 32-bit for wraparound-safe comparison
        # This handles the Y2038 edge case where timestamps wrap
        now_signed = struct.unpack('>i', struct.pack('>I', now & 0xFFFFFFFF))[0]
        expires_signed = struct.unpack('>i', struct.pack('>I', expires_at & 0xFFFFFFFF))[0]

        # Check: is current time before expiry?
        # Using signed difference to handle wraparound
        diff = expires_signed - now_signed

        # Session is valid if expiry is in the future (diff > 0)
        # OR if the session was created very recently (within 5 seconds)
        # to handle clock synchronization issues
        if diff > 0:
            return True

        # Grace period check for recently created sessions
        created_diff = now - created_at
        if created_diff < 5:
            return True

        return False

    def revoke_session(self, session_id):
        self._sessions.pop(session_id, None)


store = SessionStore()


class AuthHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path == '/auth/login':
            self._handle_login()
        elif self.path == '/auth/validate':
            self._handle_validate()
        elif self.path == '/admin/users':
            self._handle_admin_users()
        else:
            self._send_response(404, {'error': 'not found'})

    def do_GET(self):
        if self.path == '/health':
            self._send_response(200, {'status': 'ok'})
        elif self.path == '/admin/stats':
            self._handle_admin_stats()
        else:
            self._send_response(404, {'error': 'not found'})

    def _handle_login(self):
        body = self._read_body()
        if not body:
            self._send_response(400, {'error': 'invalid request'})
            return

        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._send_response(400, {'error': 'invalid json'})
            return

        username = data.get('username', '')
        password = data.get('password', '')

        # Simplified auth - in production would check against DB
        user_id, role = self._authenticate_user(username, password)
        if user_id is None:
            self._send_response(401, {'error': 'authentication failed'})
            return

        session_id, token = store.create_session(user_id, role)
        self._send_response(200, {'token': token, 'expires_in': SESSION_DURATION})

    def _authenticate_user(self, username, password):
        # Demo authentication - would use bcrypt/argon2 in production
        users = {
            'admin': {'id': 1, 'role': 'admin', 'pw_hash': hashlib.sha256(b'admin_secret_pw').hexdigest()},
            'user1': {'id': 2, 'role': 'user', 'pw_hash': hashlib.sha256(b'user1_pw').hexdigest()},
        }
        user = users.get(username)
        if not user:
            return None, None

        pw_hash = hashlib.sha256(password.encode()).hexdigest()
        if not hmac.compare_digest(pw_hash, user['pw_hash']):
            return None, None

        return user['id'], user['role']

    def _handle_validate(self):
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self._send_response(401, {'error': 'missing token'})
            return

        token = auth_header[7:]
        session = store.validate_token(token)
        if session is None:
            self._send_response(401, {'error': 'invalid or expired token'})
            return

        self._send_response(200, {'valid': True, 'user_id': session['user_id'], 'role': session['role']})

    def _handle_admin_stats(self):
        session = self._require_admin()
        if session is None:
            return
        self._send_response(200, {'active_sessions': len(store._sessions)})

    def _handle_admin_users(self):
        session = self._require_admin()
        if session is None:
            return
        self._send_response(200, {'users': ['admin', 'user1']})

    def _require_admin(self):
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self._send_response(401, {'error': 'missing token'})
            return None

        token = auth_header[7:]
        session = store.validate_token(token)
        if session is None:
            self._send_response(401, {'error': 'invalid or expired token'})
            return None

        if session['role'] != 'admin':
            self._send_response(403, {'error': 'admin required'})
            return None

        return session

    def _read_body(self):
        try:
            length = int(self.headers.get('Content-Length', 0))
            if length > 65536:
                return None
            return self.rfile.read(length)
        except (ValueError, TypeError):
            return None

    def _send_response(self, code, data):
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        body = json.dumps(data).encode()
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format, *args):
        pass  # Suppress default logging


def main():
    server = HTTPServer(('127.0.0.1', 8080), AuthHandler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        server.shutdown()


if __name__ == '__main__':
    main()
